def _m(title, url, purpose, label, when, steps, expected, controls=()):
    return {"surface": "admin", "title": title, "url_path": url, "purpose": purpose,
            "prerequisites": ["Admin login"],
            "actions": [{"id": "main", "label": label, "when": when, "steps": steps, "expected": expected,
                         "controls": [{"name": n, "desc": d} for n, d in controls]}]}


